// Jendela SATU: jam operasional outlet 06:00-21:59:59 WIB HARI INI,
// dipakai bersama oleh 4 cabang platform di bawah -- pola identik
// 'cd.timeRange' pada workflow lama 'All - Get Product Details'
// (termasuk teknik toWIBISOString: tambah 7 jam lalu format pakai
// getter UTC, supaya angka jam yang tercetak benar WIB walau Date
// internalnya tetap instant UTC asli -- bukan konversi timezone asli,
// sengaja replikasi persis trik yang sudah dipakai & terbukti jalan).
// Workflow ini jalan tiap jam (bukan sekali sehari), jadi TIDAK pakai
// windowDays mundur n-hari seperti raw-majoo-direct.json.
const now = new Date();
const wibNow = new Date(now.getTime() + 7 * 3600 * 1000);
const y = wibNow.getUTCFullYear();
const m = String(wibNow.getUTCMonth() + 1).padStart(2, '0');
const d = String(wibNow.getUTCDate()).padStart(2, '0');

const start = new Date(`${y}-${m}-${d}T06:00:00+07:00`);
const finish = new Date(`${y}-${m}-${d}T21:59:59+07:00`);

function toWIBISOString(date) {
  const wib = new Date(date.getTime() + 7 * 60 * 60 * 1000);
  const yy = wib.getUTCFullYear();
  const mm = String(wib.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(wib.getUTCDate()).padStart(2, '0');
  const hh = String(wib.getUTCHours()).padStart(2, '0');
  const mi = String(wib.getUTCMinutes()).padStart(2, '0');
  const ss = String(wib.getUTCSeconds()).padStart(2, '0');
  return `${yy}-${mm}-${dd}T${hh}:${mi}:${ss}+07:00`;
}

return [{ json: {
  startTime: Math.floor(start.getTime() / 1000),
  endTime: Math.floor(finish.getTime() / 1000),
  start_iso: toWIBISOString(start),
  end_iso: toWIBISOString(finish),
  majoo_start: `${y}-${m}-${d} 00:00`,
  majoo_end: `${y}-${m}-${d} 23:59`,
} }];

const row = $input.item.json;
if (!row) throw new Error('Token Shopee tidak ditemukan di api_tokens untuk platform shopeefood');
if (row.status !== 'valid') throw new Error(`Token Shopee status: ${row.status} -- cek dan refresh manual dulu di api_tokens`);
if (row.expires_at && new Date(row.expires_at) < new Date()) throw new Error(`Token Shopee sudah expired pada ${row.expires_at} -- refresh manual dulu`);

let tokenHeaders;
try { tokenHeaders = typeof row.token === 'string' ? JSON.parse(row.token) : row.token; }
catch (e) { throw new Error('Kolom token Shopee bukan JSON valid'); }

// Header fingerprint browser generik TAMBAHAN -- TIDAK tersimpan di
// token (cuma 10 key inti), tapi disertakan workflow lama di endpoint
// yang lebih lengkap (Fetch Settlement List) -- disamakan di semua
// request Shopee demi konsistensi/keamanan.
const headers = {
  ...tokenHeaders,
  priority: 'u=1, i',
  'sec-ch-ua': '"Google Chrome";v="149", "Chromium";v="149", "Not)A;Brand";v="24"',
  'sec-ch-ua-mobile': '?0',
  'sec-ch-ua-platform': '"macOS"',
  'sec-fetch-dest': 'empty',
  'sec-fetch-mode': 'cors',
  'sec-fetch-site': 'same-site',
};

const waktu = $('Tentukan Jendela Waktu').first().json;
return [{ json: { headers, startTime: waktu.startTime, endTime: waktu.endTime } }];

// Paginasi DITAMBAHKAN di sini (workflow lama 'All - Get Product
// Details' hardcode pageNo:1 saja -- berisiko transaksi terpotong
// diam-diam kalau rame). Pola while-loop ini SAMA seperti yang
// sudah terbukti jalan di 'Fetch Settlement List' (workflow 'Get
// sales & biaya online', endpoint beda tapi mekanisme identik).
const ctx = $input.item.json;
const { headers, startTime, endTime } = ctx;

let allRows = [];
let pageNo = 1;
const pageSize = 100;

while (true) {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.partner.shopee.co.id/nb/mss/web-api/PartnerTransactionServer/GetTransactionList',
    headers,
    body: {
      pageNo, pageSize,
      filter: { startTime, endTime, serviceList: [2] },
      sorter: { field: 'createTime', order: 'ascend' },
    },
    json: true,
    ignoreHttpStatusErrors: true,
  });

  const rows = (response && response.data && response.data.list) || [];
  allRows = allRows.concat(rows);

  if (rows.length < pageSize) break;
  pageNo++;
}

// hanya ShopeeFood (service===2) & transaksi sukses (status===4) --
// sama seperti filter 'cd.shopee.completedOrders' workflow lama.
const selesai = allRows.filter(r => Number(r.service) === 2 && Number(r.status) === 4);

return selesai.map(r => ({ json: { ...r, headers } }));

// -> 12 kolom KOLOM_LOG. TANPA resolusi alias Google Sheets (item_name
// dikirim apa adanya dari platform). menu_id DIISI SAMA DENGAN
// item_name (bukan kosong) -- syncItemMappingFromLog
// (import-csv.ts:421) HANYA mengantrikan baris untuk dipetakan kalau
// menu_id terisi (lihat item-mapping.ts:74); menu_id kosong membuat
// /sales-sync/proses melewati SELURUH order tanpa jalan untuk
// memetakannya lewat UI (ditemukan dari insiden produksi 2026-10-29,
// 53 order tersangkut). unique_key JUGA pakai nama mentah yang sama.
const output = [];

for (const input of $input.all()) {
  const order = input.json.data && input.json.data.order;
  if (!order) continue;

  const orderDate = new Date(Number(order.create_time) * (Number(order.create_time) < 2e10 ? 1000 : 1));
  const transaction_date = orderDate.toLocaleDateString('en-US', { timeZone: 'Asia/Jakarta' });
  const transaction_time = orderDate.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Asia/Jakarta' });

  for (const item of order.items || []) {
    const rawMenuName = (item.cart_item && item.cart_item.detail && item.cart_item.detail.dish && item.cart_item.detail.dish.name) || '';
    const qty = (item.cart_item && item.cart_item.quantity) || 1;

    output.push({ json: {
      transaction_date, transaction_time,
      platform: 'Shopee',
      order_id: order.id,
      item_name: rawMenuName,
      menu_id: rawMenuName,
      quantity: qty,
      item_type: 'menu',
      parent_item: '',
      unique_key: `Shopee|${order.id}|${rawMenuName}|menu`,
    } });

    const optionGroups = (item.cart_item && item.cart_item.detail && item.cart_item.detail.option_groups) || [];
    for (const group of optionGroups) {
      const groupName = (group.name || '').toLowerCase();
      const isAddon = groupName.includes('bundling') || groupName.includes('add on');
      if (!isAddon) continue;
      for (const option of group.options || []) {
        if (!option.price || Number(option.price) <= 0) continue;
        output.push({ json: {
          transaction_date, transaction_time,
          platform: 'Shopee',
          order_id: order.id,
          item_name: option.name,
          menu_id: option.name,
          quantity: qty,
          item_type: 'addon',
          parent_item: rawMenuName,
          unique_key: `Shopee|${order.id}|${option.name}|addon`,
        } });
      }
    }
  }
}

return output;

