// -> 12 kolom KOLOM_LOG. unique_key DISAMAKAN ke nama MENTAH
// (keputusan AskUserQuestion) -- workflow lama GrabFood satu-satunya
// yang pakai nama STANDAR hasil alias, di sini disamakan ke pola 3
// platform lain. TANPA resolusi alias (item_name apa adanya). menu_id
// DIISI SAMA DENGAN item_name (bukan kosong) -- lihat catatan di node
// 'Petakan Baris Shopee' soal kenapa menu_id TIDAK BOLEH kosong.
const output = [];

for (const input of $input.all()) {
  const order = input.json.order;
  if (!order) continue;

  const orderDate = new Date(order.times.createdAt);
  const transaction_date = orderDate.toLocaleDateString('en-US', { timeZone: 'Asia/Jakarta' });
  const transaction_time = orderDate.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Asia/Jakarta' });

  for (const item of (order.itemInfo && order.itemInfo.items) || []) {
    output.push({ json: {
      transaction_date, transaction_time,
      platform: 'GrabFood',
      order_id: order.orderID,
      item_name: item.name,
      menu_id: item.name,
      quantity: item.quantity,
      item_type: 'menu',
      parent_item: '',
      unique_key: `GrabFood|${order.orderID}|${item.name}|menu`,
    } });

    for (const group of item.modifierGroups || []) {
      for (const modifier of group.modifiers || []) {
        const priceStr = String(modifier.priceDisplay || '0').replace(',', '.').trim();
        if (parseFloat(priceStr) === 0) continue;
        output.push({ json: {
          transaction_date, transaction_time,
          platform: 'GrabFood',
          order_id: order.orderID,
          item_name: modifier.modifierName,
          menu_id: modifier.modifierName,
          quantity: modifier.quantity || item.quantity,
          item_type: 'addon',
          parent_item: item.name,
          unique_key: `GrabFood|${order.orderID}|${modifier.modifierName}|addon`,
        } });
      }
    }
  }
}

return output;

