while (true) {
  const url = `https://api.gojekapi.com/merchant-analytics/v2/merchants/transactions?from=${from}&size=${size}&statuses=SETTLEMENT,CAPTURE,REFUND,PARTIAL_REFUND&payment_types=QRIS,GOPAY,OFFLINE_CREDIT_CARD,OFFLINE_DEBIT_CARD,CREDIT_CARD&start_time=${start_iso}&end_time=${end_iso}&merchant_ids=G426274732`;

