// -> 12 kolom KOLOM_LOG. Filter is_refundable!==0 (skip SELURUH
// transaksi yang masih bisa direfund) DIREPLIKASI APA ADANYA dari
// workflow lama -- keputusan sadar, bukan oversight (lihat README).
// menu_id DIISI SAMA DENGAN item_name (bukan kosong) -- lihat catatan
// di node 'Petakan Baris Shopee' soal kenapa menu_id TIDAK BOLEH
// kosong.
const output = [];

for (const input of $input.all()) {
  const response = input.json;
  if (!response.data || response.data.is_refundable !== 0) continue;

  const info = response.data.info || {};
  const details = response.data.detail || [];
  const refunds = response.data.refund || [];
  const orderNumber = info.invoice_number || '';

  const orderHour = info.order_hour || '';
  const [datePart, timePart] = orderHour.split(' ');
  const transaction_time = timePart ? timePart.slice(0, 5) : '';
  const [y, m, dd] = (datePart || '').split('-');
  const transaction_date = (y && m && dd) ? `${parseInt(m, 10)}/${parseInt(dd, 10)}/${y}` : '';

  for (const item of details) {
    output.push({ json: {
      transaction_date, transaction_time,
      platform: 'Majoo',
      order_id: orderNumber,
      item_name: item.product_name,
      menu_id: item.product_name,
      quantity: item.quantity,
      item_type: 'menu',
      parent_item: '',
      unique_key: `Majoo|${response.data.id || orderNumber}|${item.product_name}|menu`,
    } });

    for (const addon of item.item_addon_detail || []) {
      if (!addon.price) continue;
      output.push({ json: {
        transaction_date, transaction_time,
        platform: 'Majoo',
        order_id: orderNumber,
        item_name: addon.addon_name,
        menu_id: addon.addon_name,
        quantity: addon.quantity,
        item_type: 'addon',
        parent_item: item.product_name,
        unique_key: `Majoo|${response.data.id || orderNumber}|${addon.addon_name}|addon`,
      } });
    }
  }

  for (const refund of refunds) {
    const refundParts = (refund.date || '').split(' ');
    const refundDatePart = refundParts[0] || datePart;
    const refundTimePart = refundParts[1] ? refundParts[1].slice(0, 5) : transaction_time;
    const [ry, rm, rd] = (refundDatePart || '').split('-');
    const refund_date = (ry && rm && rd) ? `${parseInt(rm, 10)}/${parseInt(rd, 10)}/${ry}` : transaction_date;

    for (const rp of refund.products || []) {
      if (!rp.qty) continue;
      const matchedDetail = details.find(dt => dt.product_id === rp.id);
      const rawName = matchedDetail ? matchedDetail.product_name : `ProductID:${rp.id}`;
      output.push({ json: {
        transaction_date: refund_date, transaction_time: refundTimePart,
        platform: 'Majoo',
        order_id: orderNumber,
        item_name: rawName,
        menu_id: rawName,
        quantity: -rp.qty,
        item_type: 'refund',
        parent_item: '',
        unique_key: `Majoo|${response.data.id || orderNumber}|${rawName}|refund`,
      } });
    }
  }
}

return output;

function csvField(v) {
  const s = v === null || v === undefined ? "" : String(v);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function buatBarisCsv(header, obj) {
  return header.map((h) => csvField(obj[h])).join(",");
}

const mode = $('Simpan Token & Mode').first().json;
const { dryRun, token } = mode;
const HEADER = ["transaction_date","transaction_time","platform","order_id","item_name","menu_id","quantity","item_type","parent_item","unique_key","inv_status"];
const MAKS_BARIS = 50000;

// TIDAK ada filter cutoff tanggal di sini -- beda sengaja dari
// log-penjualan.json, jendela waktu sudah ditentukan di hulu lewat
// 'Tentukan Jendela Waktu' per cabang platform (pola sama seperti
// penyesuaian Fase 1 raw-majoo-direct.json).
const baris = [];
for (const item of $input.all()) {
  const row = item.json;
  const obj = {};
  for (const kolom of HEADER) obj[kolom] = row[kolom] ?? "";
  if (!obj.inv_status) obj.inv_status = "OK";
  baris.push(obj);
}

if (dryRun) {
  return [{
    json: {
      dryRun: true,
      jumlahBaris: baris.length,
      contohBaris: baris.slice(0, 3),
      csvHeader: HEADER.join(","),
    },
  }];
}

const hasil = [];
for (let i = 0; i < baris.length; i += MAKS_BARIS) {
  const potongan = baris.slice(i, i + MAKS_BARIS);
  const lines = [HEADER.join(",")];
  for (const obj of potongan) lines.push(buatBarisCsv(HEADER, obj));
  hasil.push({
    json: {
      dryRun: false,
      token,
      csvText: lines.join("\n") + "\n",
      jumlahBarisBatch: potongan.length,
      batchKe: Math.floor(i / MAKS_BARIS) + 1,
    },
  });
}
if (hasil.length === 0) {
  hasil.push({ json: { dryRun: false, token, csvText: HEADER.join(",") + "\n", jumlahBarisBatch: 0, batchKe: 1 } });
}
return hasil;
